                f.write(resp.content)
            return True
        return False
    except Exception:
        return False


def _read_tracker_text():
    """Downloads the tracker and attempts to extract text content for inspection."""
    local = "/tmp/_tracker_check.xlsx"
    ok = _download_owncloud_file(
        "Documents/Vendor_Contracts/Vendor_Contract_Tracker.xlsx", local
    )
    if not ok or not os.path.exists(local):
        return None
    try:
        import openpyxl
        wb = openpyxl.load_workbook(local, data_only=True)
